export const getOfficerRole = (designation: string) => {
  const norm = designation || "District Agriculture Officer";
  if (norm.includes("Village Secretary")) return ROLE_HIERARCHY["Village Secretary"];
  if (norm.includes("Block Extension Officer")) return ROLE_HIERARCHY["Block Extension Officer"];
  if (norm.includes("District Agriculture Officer")) return ROLE_HIERARCHY["District Agriculture Officer"];
  if (norm.includes("State Agriculture Director")) return ROLE_HIERARCHY["State Agriculture Director"];
  
  // Backwards compatibility with previous options
  if (norm.includes("Technical Inspector")) return ROLE_HIERARCHY["Block Extension Officer"];
  if (norm.includes("Joint Director")) return ROLE_HIERARCHY["District Agriculture Officer"];
  return ROLE_HIERARCHY["District Agriculture Officer"];
};

