export const getFullSchemeDetails = (scheme: any) => {
  if (!scheme) return null;
  const fallback = SCHEME_DETAILS_FALLBACKS[scheme.id];
  
  return {
    ...scheme,
    department: scheme.department || fallback?.department || "Department of Agricultural Development",
    eligibility: scheme.eligibility || fallback?.eligibility || [
      `Active farmers registered in ${scheme.state || "Andhra Pradesh"}`,
      "Must own cultivable land and have land records updated in the portal",
      "Must comply with standard ecological guidelines (zero stubble burning, eco-friendly water management)"
    ],
    benefits: scheme.benefits || fallback?.benefits || [
      `Direct subsidy funding of up to ₹${(scheme.budgetAllocated * 0.005).toLocaleString()} per qualified farm unit`,
      "Technical guidance, seed quality checking, and digital training provided by Block extension offices"
    ],
    applicationProcess: scheme.applicationProcess || fallback?.applicationProcess || [
      "1. Submit digital application specifying land survey numbers and cropping plans",
      "2. Automated GIS land-mapping checks by District Agriculture officers",
      "3. On-site verification or physical audit by village-level field officers",
      "4. Public list publication and automated direct benefit bank transfer"
    ],
    documentsRequired: scheme.documentsRequired || fallback?.documentsRequired || [
      "Aadhaar Card (identity proof)",
      "Land Possession Deed or Land Registry record (Khasra/Jamabandi)",
      "Aadhaar-linked Bank Passbook copy",
      "Self-Declaration regarding matching guidelines"
    ]
  };
};

export const getSchemeApplications = (schemeId: string, schemeName: string, applications: any[]) => {
  const realApps = applications.filter(app => 
    app.schemeId === schemeId || 
    (app.schemeName && app.schemeName.toLowerCase().includes(schemeName.toLowerCase())) ||
    (schemeName && schemeName.toLowerCase().includes(app.schemeName?.toLowerCase()))
  );
  
  const mockFarmersList = [
    { name: "Karan Singh", village: "Ghuman", district: "Machilipatnam", date: "2026-07-01", status: "Approved" },
    { name: "Sukhwinder Kaur", village: "Dhariwal", district: "Machilipatnam", date: "2026-07-05", status: "Pending" },
    { name: "Rajinder Prasad", village: "Harsa Chhina", district: "Vijayawada", date: "2026-06-18", status: "Rejected" },
    { name: "Gurpreet Singh", village: "Rayya", district: "Vijayawada", date: "2026-07-12", status: "Pending" },
    { name: "Baldev Singh", village: "Majitha", district: "Vijayawada", date: "2026-07-02", status: "Approved" },
    { name: "Manpreet Dhillon", village: "Ghuman", district: "Machilipatnam", date: "2026-06-29", status: "Approved" }
  ];

  const seededApps: any[] = [];
  
  realApps.forEach(app => {
    seededApps.push({
      id: app.id,
      farmerName: app.farmerName,
      location: "Machilipatnam, Andhra Pradesh",
      date: app.submittedDate || "2026-07-10",
      status: app.status === "Action Required" ? "Pending" : app.status === "Under Review" ? "Pending" : app.status
    });
  });

  const remainingCount = Math.max(5 - seededApps.length, 3);
  for (let i = 0; i < remainingCount; i++) {
    const farmer = mockFarmersList[i % mockFarmersList.length];
    const appIndexId = `APP-${schemeId.replace("scheme-db-", "")}0${i + 4}`;
    seededApps.push({
      id: appIndexId,
      farmerName: farmer.name,
      location: `${farmer.village}, ${farmer.district}`,
      date: farmer.date,
      status: i === 0 ? "Pending" : i === 1 ? "Approved" : "Rejected"
    });
  }

  return seededApps;
};

