export interface CropProductionStats {
  cropName: string;
  productionTons: number;
  yieldPerAcre: number;
  croppedArea: number;
  changeDir: "up" | "down";
  changePct: number;
}

export interface FarmerProductionData {
  farmerId: string;
  farmerName: string;
  croppedArea: number;
  cropName: string;
  variety: string;
  productionTons: number;
  yieldPerAcre: number;
  fertilizerUsage: string;
  pesticideUsage: string;
  status: "Excellent" | "Optimal" | "Deficit";
}

export interface VillageProductionData {
  villageId: string;
  villageName: string;
  totalArea: number;
  farmers: FarmerProductionData[];
}

export interface BlockProductionData {
  blockId: string;
  blockName: string;
  totalArea: number;
  performance: "Top Performer" | "High Yield" | "Moderate" | "Needs Attention";
  crops: { cropName: string; productionTons: number; yieldPerAcre: number }[];
  villages: VillageProductionData[];
}

export interface DistrictProductionData {
  districtName: string;
  totalArea: number;
  changePct: number;
  changeDir: "up" | "down";
  crops: CropProductionStats[];
  blocks: BlockProductionData[];
}

