    const targetFarmer = farmers.find(f => f.id === id);
    const farmerName = targetFarmer ? targetFarmer.name : "Unknown Farmer";
    const fullReason = `REVOKED: ${reason.toUpperCase()}`;

    const updated = farmers.map((f) => {
      if (f.id === id) {
        return {
          ...f,
          status: "Rejected" as const,
          activeStatus: "Inactive" as const,
          revoked: true,
          rejectionReason: fullReason,
          verificationDate: undefined,
          verificationOfficer: undefined
        };
      }
      return f;
    });
    setFarmers(updated);
    localStorage.setItem("agriconnect_all_farmers", JSON.stringify(updated));
    logVerification(id, farmerName, "Officer Rajesh Sharma", "Rejected", fullReason);
    alert(`Verification revoked for farmer. Status set to Inactive and Rejected due to fraud/violation.`);
    setSelectedFarmer(null);
