  const handleExportStandardReport = (format: "csv" | "excel" | "json" | "pdf") => {
    if (!standardReportResults) return;
    const { id, title, subtitle, summary, data } = standardReportResults;
    let filename = `${id}.${format === "excel" ? "xls" : format}`;
    let content = "";
    let mimeType = "text/plain";

    if (format === "json") {
      content = JSON.stringify(standardReportResults, null, 2);
      mimeType = "application/json";
    } else if (format === "csv" || format === "excel") {
      const separator = format === "excel" ? "\t" : ",";
      mimeType = format === "excel" ? "application/vnd.ms-excel" : "text/csv";

      let fileBody = `${title}\n${subtitle}\nReport ID: ${id}\nGenerated At: ${new Date().toLocaleString()}\n\n`;
      Object.entries(summary).forEach(([key, val]) => {
        fileBody += `${key}${separator}${val}\n`;
      });
      fileBody += "\n";

      const keys = Object.keys(data[0] || {});
      fileBody += keys.join(separator) + "\n";

      data.forEach((row: any) => {
        const cleanRow = keys.map(k => {
          const val = row[k];
          if (typeof val === "string") {
            return `"${val.replace(/"/g, '""')}"`;
          }
          return val;
        });
        fileBody += cleanRow.join(separator) + "\n";
      });
      content = fileBody;
    } else if (format === "pdf") {
      mimeType = "application/pdf";
      let pdfLayout = `========================================================================\n`;
      pdfLayout += `               GOVERNMENT OF INDIA - AGRICULTURAL PORTAL                 \n`;
      pdfLayout += `                      OFFICIAL STANDARD COMPLIANCE LOG                  \n`;
      pdfLayout += `========================================================================\n\n`;
      pdfLayout += `REPORT ID    : ${id}\n`;
      pdfLayout += `TITLE        : ${title}\n`;
      pdfLayout += `SUBTITLE     : ${subtitle}\n`;
      pdfLayout += `GENERATED AT : ${new Date().toLocaleString()}\n`;
      pdfLayout += `AUTHORITY    : Digital Agri Administration Dept\n\n`;
      pdfLayout += `------------------------------------------------------------------------\n`;
      pdfLayout += `                          EXECUTIVE SUMMARY                             \n`;
      pdfLayout += `------------------------------------------------------------------------\n`;
      Object.entries(summary).forEach(([key, val]) => {
        pdfLayout += `${key.replace(/([A-Z])/g, ' $1').toUpperCase()} : ${val}\n`;
      });
      pdfLayout += `------------------------------------------------------------------------\n\n`;
      pdfLayout += `------------------------------------------------------------------------\n`;
      pdfLayout += `                             DETAILED ENTRIES                           \n`;
      pdfLayout += `------------------------------------------------------------------------\n`;

      data.forEach((row: any, idx: number) => {
        pdfLayout += `Entry #${idx + 1}:\n`;
        Object.entries(row).forEach(([k, v]) => {
          pdfLayout += `  ${k.toUpperCase()}: ${v}\n`;
        });
        pdfLayout += `\n`;
      });
      pdfLayout += `========================================================================\n`;
      content = pdfLayout;
    }

    const blob = new Blob([content], { type: mimeType });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    link.click();
  };

