  const handleRunPlaygroundRequest = () => {
    setIsPlayingRequest(true);
    setPlaygroundResponse("");
    
    setTimeout(() => {
      // Filter the data
      let filtered = [...HISTORICAL_PRODUCTION_DATA];
      if (playgroundDistrict !== "All") {
        filtered = filtered.filter(rec => rec.district === playgroundDistrict);
      }
      if (playgroundYear !== "All") {
        filtered = filtered.filter(rec => rec.year.toString() === playgroundYear);
      }
      
      const subset = filtered.slice(0, 4);
      
      let formattedBody = "";
      if (playgroundFormat === "json") {
        formattedBody = JSON.stringify({
          status: "success",
          count: filtered.length,
          executionTimeMs: 14,
          data: subset,
          message: filtered.length > 4 ? `Showing first 4 records of ${filtered.length}. Use ?limit=${filtered.length} to retrieve full dataset.` : "All records retrieved matching filter criteria."
        }, null, 2);
      } else if (playgroundFormat === "xml") {
        formattedBody = `<?xml version="1.0" encoding="UTF-8"?>
<ApiResponse>
  <Status>success</Status>
  <Count>${filtered.length}</Count>
  <Records>
` + subset.map(item => `    <Record>
      <Year>${item.year}</Year>
      <District>${item.district}</District>
      <Block>${item.block}</Block>
      <Season>${item.season}</Season>
      <Crop>${item.cropName}</Crop>
      <Yield>${item.yieldPerAcre.toFixed(2)}</Yield>
    </Record>`).join("\n") + `
  </Records>
</ApiResponse>`;
      } else {
        // CSV format
        const headers = "year,district,block,season,crop,yield";
        const rows = subset.map(item => `${item.year},"${item.district}","${item.block}","${item.season}","${item.cropName}",${item.yieldPerAcre.toFixed(2)}`).join("\n");
        formattedBody = `${headers}\n${rows}\n... (${filtered.length - subset.length} more records truncated)`;
      }
      
      setPlaygroundResponse(formattedBody);
      setIsPlayingRequest(false);
    }, 1500);
  };

